// Regeneration Cradle - maturation scheduler (Mark 1 demonstration run) [concept study]
// Run with: node demo.js
'use strict';
var fid=[82,96,99.9], mat=[420,60,7];
console.log("Regeneration Cradle - growth program by generation");
console.log("==================================================");
for(var m=0;m<3;m++){
  var stages=["initiation","differentiation","maturation","validation"];
  console.log("Mark "+(m+1)+": fidelity "+fid[m]+"%, full cycle "+mat[m]+" days");
  var line=" ";
  for(var s=0;s<stages.length;s++){ line+=stages[s]+"="+(mat[m]/4).toFixed(1)+"d "; }
  console.log(line);
}
console.log("Consent and identity-rights review mandatory at every stage.");

